('12-CHE-CK-0001','TS-Inter-2,MPC,BiPC,JEE','Chemistry','Chemical Kinetics','Rate','Easy',0,NULL,'Rate of reaction is','Change in concentration per unit time','Mass per time','Volume per time','Temperature per time','A','r = -d[R]/dt = d[P]/dt.',NULL,1,NOW()),
('12-CHE-CK-0002','TS-Inter-2,MPC,BiPC,JEE','Chemistry','Chemical Kinetics','Order','Medium',0,NULL,'Order of reaction is','Sum of powers of concentration terms in rate law','Always 1','Always 2','Stoichiometric coefficient','A','Determined experimentally, not from equation.',NULL,1,NOW()),
('12-CHE-CK-0003','TS-Inter-2,MPC,BiPC,JEE','Chemistry','Chemical Kinetics','First Order','Medium',0,NULL,'For first order reaction, rate law is','r = k[A]','r = k[A]^2','r = k','r = k[A]^0','A','Rate proportional to concentration.',NULL,1,NOW()),
('12-CHE-CK-0004','TS-Inter-2,MPC,BiPC,JEE','Chemistry','Chemical Kinetics','Half Life 1','Medium',1,2019,'Half-life of first order reaction: t_1/2 = ','0.693/k','1/k','k/0.693','2/k','A','Independent of initial concentration.',NULL,1,NOW()),
('12-CHE-CK-0005','TS-Inter-2,MPC,BiPC,JEE','Chemistry','Chemical Kinetics','k First','Medium',0,NULL,'Rate constant for first order: k = ','(2.303/t)log(a/(a-x))','(1/t)(1/(a-x) - 1/a)','x/t','a/t','A','Integrated rate law.',NULL,1,NOW()),
('12-CHE-CK-0006','TS-Inter-2,MPC,BiPC,JEE','Chemistry','Chemical Kinetics','Zero Order','Medium',0,NULL,'In zero order reaction, rate is','Independent of concentration (r=k)','Proportional to [A]','Proportional to [A]^2','Infinite','A','Concentration decreases linearly.',NULL,1,NOW()),
